import sys
from collections import defaultdict, deque

def solve(n, m, friendships):
    graph = defaultdict(list)
    for i, j, b in friendships:
        graph[i].append((j, b))
        graph[j].append((i, 1 - b))

    visited = [False] * (n + 1)
    incomes = [None] * (n + 1)

    def bfs(start):
        queue = deque([(start, 0)])
        while queue:
            node, income = queue.popleft()
            if visited[node]:
                continue
            visited[node] = True
            incomes[node] = income
            for neighbor, b in graph[node]:
                if not visited[neighbor]:
                    if b == 1:
                        queue.append((neighbor, income + 1))
                    else:
                        queue.append((neighbor, income - 1))

    for i in range(1, n + 1):
        if not visited[i]:
            bfs(i)

    for i, j, b in friendships:
        if b == 1 and abs(incomes[i] - incomes[j]) != 1:
            return "NO"
        if abs(incomes[i] - incomes[j]) != 1:
            return f"NO"

    max_income = max(incomes[1:])
    min_income = min(incomes[1:])
    inequality = max_income - min_income

    adjusted_incomes = [x - min_income for x in incomes[1:]]

    return f"YES\n{inequality}\n{' '.join(map(str, adjusted_incomes))}"

input = sys.stdin.read().strip().split()
n = int(input[0])
m = int(input[1])
friendships = [(int(input[3*i+2]), int(input[3*i+3]), int(input[3*i+4])) for i in range(m)]
print(solve(n, m, friendships))
